// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
    }

    function testFuzz_property(address caller, address newOwner) public {
        // caller must be a real third party; transferOwnership rejects the zero
        // address as newOwner in BOTH versions, so keep it out of the domain.
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // A non-owner third party attempts to take ownership.
        // Reference: owner() is the stored owner (address(0) here), the caller is
        // not the owner, so the call reverts and ownership is unchanged.
        // Mutant: owner() returns msg.sender == caller, so the access check
        // passes, the call succeeds, and the stored owner becomes newOwner.
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            // call succeeded (only possible in the mutant)
        } catch {
            // call reverted (the reference behaviour)
        }

        // General rule: for ANY caller and ANY candidate newOwner, the stored
        // owner remains the initial owner (address(0)); ownership cannot be
        // changed by a non-owner.
        assertTrue(c.owner() == address(0));
    }
}
